const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laJolla = ee.Geometry.Point([-117.27, 32.85]);
  const startDate = '2018-08-01';
  const endDate = '2018-08-02';

  // 2. Data Acquisition & Check
  let sstCollection = ee.ImageCollection('NOAA/CDR/SST_WHOI')
    .filterDate(startDate, endDate)
    .filterBounds(laJolla);

  const collectionSize = sstCollection.size().getInfo();
  console.log(`SST Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try alternative SST dataset
    sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
      .filterDate(startDate, endDate)
      .filterBounds(laJolla);

    const altSize = sstCollection.size().getInfo();
    console.log(`Alternative SST Images found: ${altSize}`);

    if (altSize === 0) {
      console.log("No SST data available for this date/location.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing
  const sstImage = sstCollection.mean();
  const sstBand = sstImage.select('sea_surface_temperature').multiply(0.01); // Convert to Celsius

  // Check pixel count
  const pixelCount = sstBand.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: laJolla.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('sea_surface_temperature').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation
  const sstValue = sstBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laJolla.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('sea_surface_temperature').getInfo();

  // 5. Validation & Final Answer
  console.log(`Sea Surface Temperature: ${sstValue ? sstValue.toFixed(2) : 'null'}°C`);

  if (sstValue === null || sstValue === undefined || isNaN(sstValue)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
  } else if (sstValue < -2 || sstValue > 35) {
    console.log("Temperature out of valid range.");
    console.log("<answer>C3</answer>");
  } else if (sstValue > 23) {
    console.log("Temperature exceeds 23°C.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Temperature does not exceed 23°C.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
